using System.IO.Compression;
using System.Text;

namespace MapsetVerifier.Checks.Utils.Romanisation;

/// <summary>
///     Readings of Japanese words and names, and the source spellings of loan words, from JMdict and JMnedict. The
///     list is generated by scripts/generate-japanese-words.mjs, which describes its format.
/// </summary>
public static class JapaneseDictionary
{
    /// <summary> Words longer than this aren't looked up. </summary>
    public const int MaxWordLength = 14;

    private const string ResourceName = "MapsetVerifier.Checks.japanese-words.txt.br";

    private static readonly object LoadLock = new();

    // The list is some 24 MB, so it's kept as bytes to search through rather than as hundreds of thousands of objects,
    // and may be dropped again while no beatmapset is being checked.
    private static readonly WeakReference<byte[]?> LoadedData = new(null);

    /// <summary>
    ///     The readings in hiragana of a word with kanji, or the spellings of a loan word in katakana, in lowercase
    ///     letters. Empty when the word isn't known.
    /// </summary>
    public static string[] Find(string word)
    {
        var data = GetData();
        var key = Encoding.UTF8.GetBytes(word);
        var low = 0;
        var high = data.Length;

        // Positions between lines are narrowed down to the start of the line around them.
        while (low < high)
        {
            var middle = (low + high) / 2;
            var start = data.AsSpan(0, middle).LastIndexOf((byte)'\n') + 1;
            var line = data.AsSpan(start);
            line = line[..line.IndexOf((byte)'\n')];

            var tab = line.IndexOf((byte)'\t');
            var order = line[..tab].SequenceCompareTo(key);

            if (order == 0)
                return Encoding.UTF8.GetString(line[(tab + 1)..]).Split(',');
            if (order < 0)
                low = start + line.Length + 1;
            else
                high = start;
        }

        return [];
    }

    private static byte[] GetData()
    {
        lock (LoadLock)
        {
            if (LoadedData.TryGetTarget(out var data))
                return data;

            using var resource = typeof(JapaneseDictionary).Assembly.GetManifestResourceStream(
                ResourceName
            )!;
            using var decompressed = new MemoryStream();
            using (var brotli = new BrotliStream(resource, CompressionMode.Decompress))
                brotli.CopyTo(decompressed);

            data = decompressed.ToArray();
            LoadedData.SetTarget(data);
            return data;
        }
    }
}
